package com.cyberpath.learning;
import android.app.*;
import android.content.*;
import android.os.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

/** Isolated emulator API checks. This test APK is never included in the shared app. */
public final class ReleaseSmoke extends Instrumentation {
 @Override public void onCreate(Bundle arguments){super.onCreate(arguments);start();}
 private void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 private String asset(Context context,String name)throws Exception{try(InputStream in=context.getAssets().open(name)){return new String(AppFiles.readBounded(in,5000000),StandardCharsets.UTF_8);}}
 private boolean hasPersonalAlert(Context context,String id){for(android.service.notification.StatusBarNotification notification:((NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE)).getActiveNotifications())if(notification.getTag()!=null&&notification.getTag().endsWith("-"+id))return true;return false;}
 private void personalChecks(Context context,MainActivity.NativeBridge bridge,String profile,Bundle report)throws Exception{
  java.time.ZonedDateTime now=java.time.ZonedDateTime.now();String at=java.time.Instant.now().toString(),id="reminder-native-check";
  JSONObject state=new JSONObject(bridge.getState(profile));JSONObject row=new JSONObject().put("id",id).put("title","Native alert check").put("note","A test-only personal reminder").put("date",now.minusMinutes(2).toLocalDate().toString()).put("time",now.minusMinutes(2).toLocalTime().format(java.time.format.DateTimeFormatter.ofPattern("HH:mm"))).put("notify",true).put("repeat","none").put("status","pending").put("completedAt","").put("nextId","").put("parentId","").put("editRevision",0).put("anchorDay",now.getDayOfMonth()).put("anchorMonth",now.getMonthValue()).put("createdAt",at).put("updatedAt",at);
  state.getJSONObject("learning").put("organizer",new JSONObject().put("version",1).put("items",new JSONArray().put(row)));
  require(new JSONObject(bridge.saveState(state.toString(),state.getLong("revision"),profile)).getBoolean("ok"),"Personal reminder save failed");require(PersonalReminders.allowed(context),"Test device notification permission missing");PersonalReminders.deliver(context);
  for(int i=0;i<30&&!hasPersonalAlert(context,id);i++)SystemClock.sleep(50);require(hasPersonalAlert(context,id),"Personal alert was not posted");
  state=new JSONObject(bridge.getState(profile));row=state.getJSONObject("learning").getJSONObject("organizer").getJSONArray("items").getJSONObject(0);row.put("status","completed").put("completedAt",at);
  require(new JSONObject(bridge.saveState(state.toString(),state.getLong("revision"),profile)).getBoolean("ok"),"Completed personal reminder save failed");
  for(int i=0;i<30&&hasPersonalAlert(context,id);i++)SystemClock.sleep(50);require(!hasPersonalAlert(context,id),"Completed reminder notification remained");require(PersonalReminders.status(context).getLong("nextAt")==0,"Completed reminder still has an alarm");
  state=new JSONObject(bridge.getState(profile));row=state.getJSONObject("learning").getJSONObject("organizer").getJSONArray("items").getJSONObject(0);row.put("status","pending").put("completedAt","").put("date",now.plusDays(1).toLocalDate().toString()).put("time","18:30").put("editRevision",1);
  require(new JSONObject(bridge.saveState(state.toString(),state.getLong("revision"),profile)).getBoolean("ok"),"Future personal reminder save failed");require(PersonalReminders.status(context).getLong("nextAt")>System.currentTimeMillis(),"Future personal reminder was not scheduled");report.putBoolean("personal_alert_delivery_cancellation_and_reschedule",true);report.putString("personal_alarm_timing",PersonalReminders.precise(context)?"precise":"flexible");
  state=new JSONObject(bridge.getState(profile));row=state.getJSONObject("learning").getJSONObject("organizer").getJSONArray("items").getJSONObject(0);long snoozeAt=System.currentTimeMillis()+3600000;String snoozed=java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'").withZone(java.time.ZoneOffset.UTC).format(java.time.Instant.ofEpochMilli(snoozeAt));row.put("snoozedUntil",snoozed);
  require(new JSONObject(bridge.saveState(state.toString(),state.getLong("revision"),profile)).getBoolean("ok"),"Snooze save failed");require(Math.abs(PersonalReminders.status(context).getLong("nextAt")-snoozeAt)<50,"Snooze did not replace the next alert time");
  state=new JSONObject(bridge.getState(profile));row=state.getJSONObject("learning").getJSONObject("organizer").getJSONArray("items").getJSONObject(0);row.put("snoozedUntil","").put("alertDate",now.plusDays(2).toLocalDate().toString()).put("time","07:30");
  require(new JSONObject(bridge.saveState(state.toString(),state.getLong("revision"),profile)).getBoolean("ok"),"Independent alert date save failed");long alertAt=now.plusDays(2).toLocalDate().atTime(7,30).atZone(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli();require(PersonalReminders.status(context).getLong("nextAt")==alertAt,"The alert used its due date instead of its alert date");report.putBoolean("personal_snooze_and_independent_alert_date",true);
 }
 @Override public void onStart(){Bundle report=new Bundle();MainActivity activity=null;
  try{
   Context context=getTargetContext();Intent intent=new Intent(Intent.ACTION_MAIN).setClassName(context,"com.cyberpath.learning.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
   activity=(MainActivity)startActivitySync(intent);String raw="";for(int i=0;i<300;i++){raw=AppFiles.read(context);if(!raw.isEmpty())break;SystemClock.sleep(100);}
   require(!raw.isEmpty(),"The offline app did not initialize its saved workspace");JSONObject original=new JSONObject(raw);require(original.getInt("version")==2,"Workspace version mismatch");require(original.getJSONObject("courses").length()==0,"A clean install contains seeded courses");report.putBoolean("offline_startup",true);
   require(asset(context,"vendor/pdfjs/build/pdf.mjs").length()>100000,"PDF engine asset missing");require(asset(context,"app.js").contains("prepareProfileDisplay"),"Release source missing");require(!asset(context,"study-features-ui.js").contains("Switch learner"),"Old wording remains");String packagedVersion=activity.new NativeBridge().getVersion();require(!packagedVersion.isEmpty()&&asset(context,"release.js").contains(packagedVersion),"Release version missing");report.putString("app_version",packagedVersion);report.putBoolean("nested_assets_and_release_copy",true);
   java.util.List<android.content.pm.ShortcutInfo> shortcuts=context.getSystemService(android.content.pm.ShortcutManager.class).getManifestShortcuts();require(shortcuts.size()==3,"Launcher shortcuts missing");for(android.content.pm.ShortcutInfo shortcut:shortcuts){Intent launch=shortcut.getIntent();if(shortcut.getId().equals("new-reminder"))require(launch.getBooleanExtra("lwQuickReminder",false)&&"reminders".equals(launch.getStringExtra("lwRoute")),"New reminder shortcut extras are invalid");if(shortcut.getId().equals("quick-note"))require(launch.getBooleanExtra("lwQuickNote",false),"Quick note shortcut extras are invalid");}require(context.getApplicationInfo().loadIcon(context.getPackageManager()) instanceof android.graphics.drawable.AdaptiveIconDrawable,"The LW launcher icon is not adaptive");report.putBoolean("adaptive_icon_and_launcher_shortcuts",true);
   require(asset(context,"capture.js").contains("ensureCapture"),"Capture model missing");require(asset(context,"practice-tools.js").contains("rateCard"),"Practice tools missing");
   require(asset(context,"planning.js").contains("previewDeadlinePlan"),"Offline planning model missing");require(asset(context,"assessments.js").contains("expireAssessment"),"Offline tests missing");require(asset(context,"sw.js").contains("./assessments-ui.js")&&asset(context,"sw.js").contains("./planning-ui.js"),"Offline shell registration missing");report.putBoolean("offline_planning_and_assessment_assets",true);
   NativeAddonsSmoke.run(this,activity,report);NativeOfflineSmoke.rules(report);waitForIdleSync();NativeOfflineSmoke.components(this,activity,report);
   final MainActivity target=activity;runOnMainSync(target::finish);waitForIdleSync();SystemClock.sleep(300);
   NativeAddonsSmoke.focus(context,report);
   MainActivity.NativeBridge bridge=activity.new NativeBridge();String a="learner-"+java.util.UUID.randomUUID().toString().replace("-","").substring(0,24),b="learner-"+java.util.UUID.randomUUID().toString().replace("-","").substring(0,24);
   JSONObject registry=new JSONObject().put("version",1).put("activeId","default").put("profiles",new JSONArray().put(new JSONObject().put("id","default").put("name","My profile")).put(new JSONObject().put("id",a).put("name","One")).put(new JSONObject().put("id",b).put("name","Two")));
   require(new JSONObject(bridge.saveLearnerProfiles(registry.toString())).getBoolean("ok"),"Profile registry failed");require(new JSONObject(bridge.setActiveProfile(a)).getBoolean("ok"),"First profile failed");
   JSONObject stateA=new JSONObject(raw);stateA.getJSONObject("settings").put("name","One");JSONObject savedA=new JSONObject(bridge.saveState(stateA.toString(),0,a));require(savedA.getBoolean("ok"),"First profile save failed");
   personalChecks(context,bridge,a,report);NativeOfflineSmoke.transactions(context,bridge,a,report);
   require(new JSONObject(bridge.putLibraryRecord("asset-smoke",new JSONObject().put("id","smoke").put("name","Note").put("type","text/plain").put("bytes",4).put("dataURL","data:text/plain;base64,dGVzdA==").toString(),a)).getBoolean("ok"),"Attachment save failed");
   JSONObject withAsset=new JSONObject(bridge.getState(a));withAsset.getJSONObject("learning").getJSONArray("assets").put(new JSONObject().put("id","smoke").put("name","Note").put("type","text/plain").put("bytes",4).put("createdAt",java.time.Instant.now().toString()));require(new JSONObject(bridge.saveState(withAsset.toString(),withAsset.getLong("revision"),a)).getBoolean("ok"),"Asset metadata save failed");
   require(new JSONObject(bridge.setActiveProfile(b)).getBoolean("ok"),"Second profile failed");require(bridge.getState(b).isEmpty(),"Second profile inherited another workspace");require(bridge.getLibraryRecord("asset-smoke",b).isEmpty(),"Attachment leaked between profiles");
   require(!new JSONObject(bridge.saveState(stateA.toString(),savedA.getLong("revision"),a)).getBoolean("ok"),"Stale page wrote into another profile");report.putBoolean("stale_profile_write_rejected",true);
   JSONObject stateB=new JSONObject(raw);stateB.getJSONObject("settings").put("name","Two");require(new JSONObject(bridge.saveState(stateB.toString(),0,b)).getBoolean("ok"),"Second profile save failed");require(new JSONObject(bridge.saveState(stateB.toString(),0,b)).optBoolean("conflict"),"Revision conflict was not rejected");report.putBoolean("revision_conflict_rejected",true);
   NativeAddonsSmoke.archive(context,a,b,report);
   require(new JSONObject(bridge.setActiveProfile(a)).getBoolean("ok"),"Could not return to first profile");require(new JSONObject(bridge.getState(a)).getJSONObject("settings").getString("name").equals("One"),"First profile was overwritten");require(new JSONObject(bridge.getLibraryRecord("asset-smoke",a)).getString("dataURL").endsWith("dGVzdA=="),"First profile attachment changed");report.putBoolean("profile_and_file_isolation",true);
   require(new JSONObject(bridge.setActiveProfile("default")).getBoolean("ok"),"Could not restore primary profile");require(new JSONObject(bridge.getState("default")).getJSONObject("courses").length()==0,"Primary workspace changed");report.putBoolean("primary_workspace_preserved",true);report.putString("result","PASS");finish(Activity.RESULT_OK,report);
  }catch(Throwable error){report.putString("result","FAIL");report.putString("failure",error.toString());finish(Activity.RESULT_CANCELED,report);}
 }
}
